const escapeHtml=value=>String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));

const getCurrentMenuItems=()=>{const catalogue=Array.isArray(window.menuCatalogue)?window.menuCatalogue:[];const selection=Array.isArray(window.weeklyMenuSelection)?window.weeklyMenuSelection:[];return catalogue.length?selection.map(id=>catalogue.find(item=>item.id===id)).filter(Boolean):(Array.isArray(window.weeklyMenuItems)?window.weeklyMenuItems:[]);};
const menuMount=document.querySelector('#weekly-menu-items');
if(menuMount){const menuItems=getCurrentMenuItems();menuMount.className='menu-grid';menuMount.innerHTML=menuItems.map(item=>{const image=item.image?`<img src="${escapeHtml(item.image)}" alt="${escapeHtml(item.title)}">`:'<span>Menu photo</span>';const imageClass=item.image?' has-image':'';return `<article class="product-card"><div class="photo-placeholder product-photo${imageClass}">${image}<div class="dietary-badges"><span class="dietary-badge gluten-free" ${item.glutenFree?'':'hidden'} aria-label="Made without gluten">Made without gluten</span><span class="dietary-badge vegan" ${item.vegan?'':'hidden'} aria-label="Vegan">V</span></div></div><div class="product-body"><h2>${escapeHtml(item.title)}</h2><p>${escapeHtml(item.description)}</p><div class="price">${escapeHtml(item.price)}</div></div></article>`;}).join('');}

const homeMenuPreview=document.querySelector('#home-menu-preview');
if(homeMenuPreview){const previewItems=getCurrentMenuItems().slice(0,2);homeMenuPreview.innerHTML=previewItems.length?previewItems.map(item=>{const image=item.image?`<img src="${escapeHtml(item.image)}" alt="${escapeHtml(item.title)}">`:'<span>Menu photo</span>';const imageClass=item.image?' has-image':'';return `<article class="mini-card"><div class="photo-placeholder${imageClass}">${image}</div><div><h3>${escapeHtml(item.title)}</h3><p>${escapeHtml(item.description)}</p><div class="dietary-badges mini-dietary-badges"><span class="dietary-badge gluten-free" ${item.glutenFree?'':'hidden'} aria-label="Made without gluten">Made without gluten</span><span class="dietary-badge vegan" ${item.vegan?'':'hidden'} aria-label="Vegan">V</span></div><strong>${escapeHtml(item.price)}</strong></div></article>`;}).join(''):'<p class="menu-preview-empty">This week\'s treats will be added soon.</p>';}

document.querySelectorAll('.menu-toggle').forEach(btn=>{btn.addEventListener('click',()=>{const nav=document.getElementById(btn.getAttribute('aria-controls'));const open=nav.classList.toggle('open');btn.setAttribute('aria-expanded',String(open));btn.textContent=open?'Close':'Menu';});});

const socialLinks={Instagram:'https://www.instagram.com/cookiescakes.uk/',Facebook:'https://www.facebook.com/profile.php?id=61591827583888'};
document.querySelectorAll('.socials a,.social-buttons a').forEach(link=>{const name=link.textContent.trim().replace('→','').trim();if(socialLinks[name]){link.href=socialLinks[name];link.target='_blank';link.rel='noopener noreferrer';}if(name==='TikTok')link.remove();});

const customCakeFeature=document.querySelector('.feature-grid .photo-placeholder.large');
if(customCakeFeature){fetch(`portfolio-data.js?updated=${Date.now()}`).then(response=>{if(!response.ok)throw new Error('Could not load portfolio');return response.text();}).then(source=>{const match=source.match(/window\.portfolioItems\s*=\s*(\[[\s\S]*\])\s*;?\s*$/);const items=match?JSON.parse(match[1]):[];const feature=items.find(item=>item&&item.visible!==false&&item.displayAsFeature&&item.image);if(!feature)return;const image=document.createElement('img');image.src=String(feature.image).replace(/[^a-zA-Z0-9_./-]/g,'');image.alt=String(feature.title||'Featured custom cake');image.style.cssText='display:block;width:100%;height:100%;object-fit:contain;background:#f1e8f8';customCakeFeature.innerHTML='';customCakeFeature.style.display='block';customCakeFeature.style.overflow='hidden';customCakeFeature.append(image);}).catch(()=>{});}

document.querySelectorAll('.brand-logo').forEach(logo=>{logo.style.borderRadius='0';logo.style.boxShadow='none';});
document.querySelectorAll('.footer-logo').forEach(logo=>{logo.style.filter='invert(1)';});
document.querySelectorAll('.site-footer').forEach(footer=>{footer.style.background='#1f1d1e';});

const homeFeature=document.querySelector('.hero-art .photo-placeholder.large');
const homePortfolioGallery=document.querySelector('.portfolio-strip .gallery-grid');
if(homeFeature||homePortfolioGallery){fetch(`portfolio-data.js?updated=${Date.now()}`).then(response=>{if(!response.ok)throw new Error('Could not load portfolio');return response.text();}).then(source=>{const match=source.match(/window\.portfolioItems\s*=\s*(\[[\s\S]*\])\s*;?\s*$/);const items=match?JSON.parse(match[1]):[];const imageUrl=value=>String(value||'').replace(/[^a-zA-Z0-9_./-]/g,'');const homepageFeature=items.find(item=>item&&item.visible!==false&&item.displayAsHomepageFeature&&item.image);if(homeFeature&&homepageFeature){const image=document.createElement('img');image.src=imageUrl(homepageFeature.image);image.alt=String(homepageFeature.title||'Featured Cookies Cakes creation');image.style.cssText='display:block;width:100%;height:100%;object-fit:cover';homeFeature.innerHTML='';homeFeature.style.display='block';homeFeature.style.overflow='hidden';homeFeature.append(image);}if(homePortfolioGallery){const visible=items.filter(item=>item&&item.visible!==false&&item.image);const selected=visible.sort(()=>Math.random()-.5).slice(0,3);if(selected.length){homePortfolioGallery.innerHTML=selected.map((item,index)=>`<a class="home-portfolio-photo${index===0?' tall':''}" href="portfolio.html"><img src="${imageUrl(item.image)}" alt="${String(item.title||'Cookies Cakes creation').replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;').replace(/>/g,'&gt;')}"></a>`).join('');}}}).catch(()=>{});}

document.querySelectorAll('.product-photo:not(.has-image)>span:first-child,.mini-card .photo-placeholder:not(.has-image)>span:first-child').forEach(label=>{label.textContent='New item, awaiting image';});

if(customCakeFeature||homeFeature){fetch(`portfolio-data.js?featured=${Date.now()}`).then(response=>response.ok?response.text():Promise.reject()).then(source=>{const match=source.match(/window\.portfolioItems\s*=\s*(\[[\s\S]*\])\s*;?\s*$/);const items=match?JSON.parse(match[1]):[];const featuredImage=(target,item,fit)=>{if(!target||!item||item.visible!==false||!item.image)return;const image=document.createElement('img');image.src=String(item.image).replace(/[^a-zA-Z0-9_./-]/g,'');image.alt=String(item.title||'Featured Cookies Cakes creation');image.style.cssText=`display:block;width:100%;height:100%;object-fit:${fit}`;target.innerHTML='';target.style.display='block';target.style.overflow='hidden';target.append(image);};featuredImage(customCakeFeature,items.find(item=>item&&item.displayAsFeature),'contain');featuredImage(homeFeature,items.find(item=>item&&item.displayAsHomepageFeature),'cover');}).catch(()=>{});}
const tabIcon=document.querySelector('link[rel="icon"]');
if(tabIcon){tabIcon.href='favicon.png';tabIcon.type='image/png';}

const dietaryFilterButtons=document.querySelectorAll('[data-dietary-filter]');
if(dietaryFilterButtons.length){const menuCards=document.querySelectorAll('.menu-grid .product-card');const noMenuResults=document.querySelector('.no-menu-results');dietaryFilterButtons.forEach(button=>{button.addEventListener('click',()=>{const filter=button.dataset.dietaryFilter;let matches=0;dietaryFilterButtons.forEach(item=>item.classList.toggle('active',item===button));menuCards.forEach(card=>{const show=filter==='all'||Boolean(card.querySelector(`.${filter}:not([hidden])`));card.hidden=!show;if(show)matches+=1;});if(noMenuResults)noMenuResults.hidden=matches!==0;});});}

const suggestionForm=document.querySelector('#suggestion-form');
if(suggestionForm){const suggestionStatus=document.querySelector('#suggestion-status');const suggestionButton=suggestionForm.querySelector('button[type="submit"]');suggestionForm.addEventListener('submit',async event=>{event.preventDefault();const message=String(new FormData(suggestionForm).get('suggestion')||'').trim();if(!message)return; suggestionButton.disabled=true;suggestionStatus.textContent='Sending your suggestion…';try{const result=await fetch('/api/cake-suggestions',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message})});const data=await result.json().catch(()=>({}));if(!result.ok)throw new Error(data.error||'Could not send your suggestion.');suggestionForm.reset();suggestionStatus.textContent='Thank you — your suggestion has been sent to Cookies Cakes.';}catch(error){suggestionStatus.textContent=error.message||'Could not send your suggestion. Please try again.';}finally{suggestionButton.disabled=false;}});}
